            width: 100%;
            height: 12px;
            background: #e0e0e0;
            border-radius: 6px;
            overflow: hidden;
            position: relative;
            margin-top: 2px;
        }
        .exp-fill {
            height: 100%;
            background: #4caf50;
            transition: width 0.3s;
        }
        .exp-text {
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            text-align: center;
            font-size: 10px;
            line-height: 12px;
            color: #fff;
            text-shadow: 0 1px 1px rgba(0,0,0,0.5);
        }
        .stats {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 4px;
            margin: 8px 0;
        }
        .stat {
            background: #fff;
            border: 1px solid #ddd;
            border-radius: 3px;
            padding: 4px 6px;
            text-align: center;
        }
        .equip-list {
            font-size: 12px;
            color: #555;
            margin-top: 8px;
            padding: 6px;
            background: #f9f9f9;
            border-radius: 3px;
            line-height: 1.4;
        }
        .equip-item {
            margin: 2px 0;
        }
        .rarity {
            color: #8b4513;
            font-size: 11px;
        }
        .ring-bar {
            width: 100%;
            height: 10px;
            background: #e0e0e0;
            border-radius: 5px;
            overflow: hidden;
            margin-top: 2px;
        }
        .ring-fill {
            height: 100%;
            background: #d32f2f;
            transition: width 0.3s;
        }
    </style>
</head>
<body>
    <div class="status-card">
        <div class="header">战斗状态</div>

        <div class="info-row">
            <span class="label">金币:</span>
            <span class="value gold" id="gold">150 G</span>
        </div>

        <div class="info-row">
            <span class="label">角色:</span>
            <span class="value"><span id="username">{{user}}</span> Lv.<span id="level">82</span></span>
        </div>

        <div class="info-row">
            <div style="width: 100%">
                <div class="label">经验值:</div>
                <div class="exp-bar">
                    <div class="exp-fill" id="exp-fill"></div>
                    <div class="exp-text" id="exp-text"></div>
                </div>
            </div>
        </div>

        <div class="stats">
            <div class="stat">HP: <span id="hp">4000</span></div>
            <div class="stat">MP: <span id="mp">2000</span></div>
            <div class="stat">力: <span id="str">350+</span></div>
            <div class="stat">敏: <span id="agi">550</span></div>
            <div class="stat">智: <span id="int">380+</span></div>
            <div class="stat">防: <span id="def">900</span></div>
        </div>

        <div class="equip-list" id="equip-list">
            装备加载中...
        </div>

        <div class="info-row">
            <div style="width: 100%">
                <div class="label">魔戒饱食度:</div>
                <div class="ring-bar">
                    <div class="ring-fill" id="ring-fill"></div>
                </div>
            </div>
        </div>
    </div>

    <script>
        function parseData() {
            const rawData = '$1';
            const parts = rawData.split('|');

            // 解析数据
            document.getElementById('gold').textContent = parts[0] + ' G';
            document.getElementById('username').textContent = parts[2];
            document.getElementById('level').textContent = parts[3];

            // 经验值处理
            const expData = parts[4].split('/');
            const currentExp = parseInt(expData[0]);
            const maxExp = parseInt(expData[1]);
            const expPercent = (currentExp / maxExp * 100).toFixed(1);
            document.getElementById('exp-fill').style.width = expPercent + '%';
            document.getElementById('exp-text').textContent = parts[4];

            // 属性值
            document.getElementById('hp').textContent = parts[5];
            document.getElementById('mp').textContent = parts[6];
            document.getElementById('str').textContent = parts[7];
            document.getElementById('agi').textContent = parts[8];
            document.getElementById('int').textContent = parts[9];
            document.getElementById('def').textContent = parts[10];

            // 装备列表
            const equipNames = ['武器', '头部', '身体', '下装', '鞋子'];
            let equipHtml = '';
            for (let i = 0; i < 5; i++) {
                if (parts[11 + i]) {
                    equipHtml += '<div class="equip-item">' + equipNames[i] + ': ' + parts[11 + i] + '</div>';
                }
            }
            document.getElementById('equip-list').innerHTML = equipHtml;

            // 魔戒饱食度
            const ringPercent = parseInt(parts[1]);
            document.getElementById('ring-fill').style.width = ringPercent + '%';
        }

        // 初始化
        parseData();
    </script>
</body>
</html>
